import psutil
import subprocess
from os.path import expanduser
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str

logger = BackgroundLogger.Instance()


class Recovery:
    def __init__(self):
        pass

    def disk_space_issue_recovery(self):
        """
        Recover from space issue by removing .zip files.
        If available space on testline is less than 9 GM then all zip files present under /home/ute will be removed.

        :param

        :return: None

        """
        fs_path = expanduser("~")
        if self.check_system_available_space(fs_path) < 9:
            logger.warn("Available disk space is less than 9GB")
            self.clear_tmp_folder('.zip')
        if self.check_system_available_space(fs_path) < 9:
            logger.warn("Available disk space is still less than 9GB, even after clearing zip files from tmp folder")
            self.clear_zip_files(fs_path)
        logger.debug("Disk space available is {} GB".format(self.check_system_available_space(fs_path)))

    def clear_zip_files(self, path_to_be_cleared):
        """Clears all zip files present under path_to_be_cleared directory. Clears from all sub folders as well but
        Excludes hidden directories like .config/.wireshark/.ute_env etc

        :param path_to_be_cleared: str, path of the directory from where .zip files has to be removed.

        :return: None
        """
        logger.debug("Clearing .zip files from {}".format(path_to_be_cleared))
        failed_to_remove = []
        try:
            list_of_zip_files = decode_str(subprocess.check_output(r'find {0} -not -path "{0}/.*" | grep -e "\.zip$"'.format(
                path_to_be_cleared), shell=True)).split("\n")
            logger.debug("zip files to be cleared {}".format(list_of_zip_files))
            if not list_of_zip_files:
                return
            for each_file in list_of_zip_files:
                try:
                    subprocess.check_output(r'rm -d {}'.format(each_file), shell=True)
                except subprocess.CalledProcessError:
                    failed_to_remove.append(each_file)
        except subprocess.CalledProcessError:
            logger.warn("No .zip files are found in the given {} path".format(path_to_be_cleared))

        logger.debug("failed to remove {} files".format(failed_to_remove))
        self.clear_tmp_folder('.zip')

    def clear_tmp_folder(self, file_type):
        """Clears given file_type from temp folder

        :param file_type: str, type of the file to be removed from tmp folder

        :return: None
        """
        logger.debug("Clearing {} files from tmp folder".format(file_type))
        try:
            list_of_files = decode_str(subprocess.check_output(r'sudo find /tmp/ | grep -e "\{}$"'.format(file_type),
                                                    shell=True)).split("\n")
            if not list_of_files:
                return
            for each_file in list_of_files:
                subprocess.check_output(r'rm -d {}'.format(each_file), shell=True)
        except subprocess.CalledProcessError:
            return

    def check_system_available_space(self, file_system):
        """Checks for disk space and return available memory in GB

        :param file_system: str, file system path on which available space should be calculated

        :return: float, available space will be returned in GB
        """
        return self._bytesto(psutil.disk_usage(file_system)[2], 'GB')

    def _bytesto(self, bytes, to, bsize=1024):
        """Converts given bytes to KB/MB/GB/TB format and returns converted value

        :param bytes: bytes, byte value to be converted.
        :param to: Value to which guven bytes to be converted. Supported types are KB/MB/GB/TB.
        :param bsize: int, size of bytes

        :return: float, converted value from byte to give type(KB/MB/GB/TB)
        """
        a = {'KB': 1, 'MB': 2, 'GB': 3, 'TB': 4}
        r = float(bytes)
        for i in range(a[to]):
            r = r / bsize
        return r
